/**
 * A4 3×5 • Dual Typeface • Second-text filler randomizer (single-letter tokens)
 * - Centered A4, 25px inner margin
 * - 5 rows with 5px vertical gap; 3 boxes/row with 5px horizontal gap
 * - Main text (default "EASY FUN TYPE PLAY"); spaces = empty boxes
 * - Non-space boxes: Randomize 1-or-2 letters per box (fixed 5px gap inside box)
 * - Font 1 auto-load:  assets/type.otf      (main text)
 * - Font 2 auto-load:  assets/type2.otf     (second text used in blank boxes)
 * - RANDOMIZER #2: when ON, fills *every* empty/unused box with **single letters**
 *   from the second text (notes are ignored). If second text is shorter than the
 *   number of blanks, it repeats so **all blanks are filled**.
 * - If filler is OFF, empty boxes show up to 4 unique multi-line notes (4 textareas)
 * - Play/Pause + speed for both randomizers
 * - Default page (canvas) color: #FF9EF7, default type color: #474EFF
 */

let ui = {};
const A_RATIO = Math.sqrt(2);
const INNER_MARGIN = 25;
const ROWS = 5;
const COLS = 3;

const ROW_GAP   = 5;   // between rows
const COL_GAP   = 5;   // between boxes in a row
const LETTER_GAP= 5;   // between letters inside a box
const LABEL_PAD = 5;   // padding for small note text

const BASE_SIZE = 1000;

// Fonts
const FONT1_CANDIDATES = ['assets/type.otf', './assets/type.otf', 'type.otf', './type.otf'];
const FONT2_CANDIDATES = ['assets/type2.ttf', './assets/type2.ttf', 'type2.ttf', './type2.ttf'];
let font1 = null, font1Ready = false, font1Err = null, font1Path = null;
let font2 = null, font2Ready = false, font2Err = null, font2Path = null;

// Randomize #1 (per non-space box: 1 or 2 letters)
let modePattern = []; // length >= 15, values 1 or 2
let autoPlay1 = false;
let lastAuto1Ms = 0;

// Randomize #2 (fill blanks with second text *single letters*)
let useSecondInBlanks = false;
let fillerTokens = []; // array of single-character strings
let autoPlay2 = false;
let lastAuto2Ms = 0;

function setup() {
  createCanvas(windowWidth, windowHeight, WEBGL);
  textAlign(LEFT, BASELINE);
  noStroke();

  buildUI();
  randomizePattern1();      // initial 1/2 pattern for main boxes
  randomizeSecondFiller();  // initial tokens for blanks (single letters)
  loadFontSequential(FONT1_CANDIDATES, (f, p)=>{font1=f;font1Ready=true;font1Path=p;}, (e)=>{font1Err=e;});
  loadFontSequential(FONT2_CANDIDATES, (f, p)=>{font2=f;font2Ready=true;font2Path=p;}, (e)=>{font2Err=e;});
}

function windowResized() { resizeCanvas(windowWidth, windowHeight); }

function draw() {
  background(ui.bgColor.value());

  const page = getA4Rect();
  fill(ui.pageColor.value());
  rect(page.x, page.y, page.w, page.h);

  const content = {
    x: page.x + INNER_MARGIN,
    y: page.y + INNER_MARGIN,
    w: page.w - 2 * INNER_MARGIN,
    h: page.h - 2 * INNER_MARGIN,
  };

  const totalGapH = ROW_GAP * (ROWS - 1);
  const rowH = (content.h - totalGapH) / ROWS;
  const totalColGap = COL_GAP * (COLS - 1);
  const colW = (content.w - totalColGap) / COLS;

  // 15 boxes
  const boxes = [];
  for (let r = 0; r < ROWS; r++) {
    const top = content.y + r * (rowH + ROW_GAP);
    for (let c = 0; c < COLS; c++) {
      const x = content.x + c * (colW + COL_GAP);
      boxes.push({ row: r, col: c, x, y: top, w: colW, h: rowH });
    }
  }

  if (ui.showGrid.checked()) drawGrid(page, content, rowH, colW);

  // AUTOPLAY #1 (pattern 1/2)
  if (autoPlay1) {
    const hz = ui.speed1.value();
    const interval = max(50, 1000 / hz);
    if (millis() - lastAuto1Ms >= interval) {
      randomizePattern1();
      lastAuto1Ms = millis();
    }
  }

  // AUTOPLAY #2 (filler tokens)
  if (autoPlay2) {
    const hz = ui.speed2.value();
    const interval = max(50, 1000 / hz);
    if (millis() - lastAuto2Ms >= interval) {
      randomizeSecondFiller();
      lastAuto2Ms = millis();
    }
  }

  const stream = (ui.textArea.value() || 'EASY FUN TYPE PLAY').toUpperCase().replace(/\n/g, ' ');
  const notes = useSecondInBlanks ? [] : getCornerNotes(); // ignore notes when second filler is ON
  let noteIdx = 0;
  let blankIdx = 0;

  fill(ui.typeColor.value());

  let i = 0;     // index into main stream
  let pat = 0;   // index into 1/2 pattern

  // IMPORTANT: iterate *all* boxes; treat any past-the-end as empty
  for (let b = 0; b < boxes.length; b++) {
    const box = boxes[b];

    let isEmpty = false;

    if (i >= stream.length) {
      // Past end of main stream → empty box
      isEmpty = true;
    } else {
      const ch = stream[i];
      if (ch === ' ') {
        isEmpty = true;
        i++; // consume the space token
      } else {
        // Non-space: place 1 or 2 letters from main stream (Font 1)
        const want = modePattern[pat] || 1;
        pat++;

        let str = ch; i++;
        if (want === 2 && i < stream.length && stream[i] !== ' ') { str += stream[i]; i++; }

        drawStringInBox(str, box, font1Ready, font1);
      }
    }

    // Handle empty boxes
    if (isEmpty) {
      if (useSecondInBlanks) {
        // Fill every empty/unused box with *single letters* from the second text.
        const tok = getSingleLetterFiller(blankIdx);
        if (tok) drawStringInBox(tok, box, font2Ready, font2);
        blankIdx++;
      } else {
        // Notes mode (only if provided)
        if (noteIdx < notes.length) {
          drawSmallNote(notes[noteIdx], box, rowH);
          noteIdx++;
        }
      }
    }
  }

  drawFontStatus(page);
}

/* ---------------- Font loading ---------------- */

function loadFontSequential(paths, onOk, onErr, idx=0) {
  if (idx >= paths.length) { onErr && onErr('All candidates failed'); return; }
  const path = paths[idx];
  loadFont(
    path,
    f => onOk && onOk(f, path),
    _ => loadFontSequential(paths, onOk, onErr, idx+1)
  );
}

/* ---------------- Drawing helpers ---------------- */

function getA4Rect() {
  const maxW = windowWidth * 0.84;
  const maxH = windowHeight * 0.90;
  let w = maxW, h = w * A_RATIO;
  if (h > maxH) { h = maxH; w = h / A_RATIO; }
  const x = (windowWidth - w) * 0.5;
  const y = (windowHeight - h) * 0.5;
  return { x, y, w, h };
}

function drawGrid(page, content, rowH, colW) {
  push();
  noFill();
  stroke(0, 0, 0, 60);
  rect(page.x, page.y, page.w, page.h);

  stroke(0, 0, 0, 40);
  rect(content.x, content.y, content.w, content.h);

  for (let r = 0; r < ROWS; r++) {
    const top = content.y + r * (rowH + ROW_GAP);
    for (let c = 0; c < COLS; c++) {
      const x = content.x + c * (colW + COL_GAP);
      stroke(0, 0, 0, 40);
      rect(x, top, colW, rowH);
    }
    // label + row-gap hint
    noStroke();
    fill(0, 0, 0, 120);
    textSize(11);
    textAlign(LEFT, TOP);
    text(`Row ${r + 1}`, content.x + 6, top + 6);
    if (r < ROWS - 1) {
      stroke(0, 0, 0, 25);
      const gy = top + rowH + ROW_GAP * 0.5;
      line(content.x, gy, content.x + content.w, gy);
    }
  }
  pop();
}

/**
 * Draw a string (1–2 chars) to exactly fill the box width & height.
 * Uses provided font (if ready) with bounds-based scaling;
 * else falls back to a system font approximation.
 */
function drawStringInBox(str, box, isReady, fontObj) {
  if (!str) return;

  if (isReady && fontObj) {
    textFont(fontObj);
    textSize(BASE_SIZE);

    const bAll = fontObj.textBounds(str, 0, 0, BASE_SIZE);
    if (!bAll || bAll.w <= 0 || bAll.h <= 0) return;
    const sy = box.h / bAll.h;

    // Per-letter bounds for widths & sidebearing removal
    const letters = [];
    for (let k = 0; k < str.length; k++) {
      const ch = str[k];
      const b = fontObj.textBounds(ch, 0, 0, BASE_SIZE);
      if (!b || b.w <= 0 || b.h <= 0) continue;
      letters.push({ ch, b });
    }
    if (letters.length === 0) return;

    const gaps = max(0, letters.length - 1);
    const totalGapPx = gaps * LETTER_GAP;

    let sumW = 0; for (const L of letters) sumW += L.b.w;
    const sx = (box.w - totalGapPx) / sumW;

    let xCursor = box.x;
    const yTopAlign = -bAll.y; // align top of ink

    push();
    noStroke();
    fill(ui.typeColor.value());
    for (let idx = 0; idx < letters.length; idx++) {
      const { ch, b } = letters[idx];
      push();
      translate(xCursor, box.y);
      scale(sx, sy);
      text(ch, -b.x, yTopAlign);
      pop();
      xCursor += b.w * sx;
      if (idx < letters.length - 1) xCursor += LETTER_GAP;
    }
    pop();

  } else {
    // Fallback system font
    textFont('sans-serif');
    textSize(BASE_SIZE);
    const asc = textAscent(), desc = textDescent(), h = asc + desc;
    const widths = []; for (let k = 0; k < str.length; k++) widths.push(textWidth(str[k]));
    let sumW = 0; for (const w of widths) sumW += w;

    const gaps = max(0, str.length - 1);
    const sx = (box.w - gaps * LETTER_GAP) / sumW;
    const sy = box.h / h;
    let xCursor = box.x;
    const yBase = box.y + box.h - desc * sy;

    push();
    noStroke();
    fill(ui.typeColor.value());
    for (let k = 0; k < str.length; k++) {
      push();
      translate(xCursor, yBase);
      scale(sx, sy);
      text(str[k], 0, 0);
      pop();
      xCursor += widths[k] * sx;
      if (k < str.length - 1) xCursor += LETTER_GAP;
    }
    pop();
  }
}

/**
 * Draw a small multi-line note (array of lines) in the top-left of an empty box.
 * Up to 4 lines; stops before overflowing the box.
 */
function drawSmallNote(lines, box, rowH) {
  if (!lines || lines.length === 0) return;

  const smallSize = constrain(rowH * 0.18, 8, 16);
  const leading = smallSize * 1.15;

  push();
  textAlign(LEFT, TOP);
  if (font1Ready && font1) textFont(font1); else textFont('sans-serif');
  textSize(smallSize);
  fill(ui.typeColor.value());

  let y = box.y + LABEL_PAD;
  const x = box.x + LABEL_PAD;
  let count = 0;
  for (let ln = 0; ln < lines.length && count < 4; ln++) {
    const line = lines[ln];
    if (y + smallSize > box.y + box.h - LABEL_PAD) break;
    text(line, x, y);
    y += leading;
    count++;
  }
  pop();
}

/* ---------------- Randomizers ---------------- */

// #1: 1-or-2 letters per non-space box
function randomizePattern1() {
  modePattern = [];
  const total = ROWS * COLS; // 15
  for (let i = 0; i < total; i++) modePattern.push(random() < 0.5 ? 1 : 2);
}

// #2: tokens for blank boxes from second text (ALWAYS single letters)
// Also ensure the token list is long enough to fill *all* boxes (so every blank is filled)
function randomizeSecondFiller() {
  fillerTokens = [];
  let raw2 = (ui.textArea2 ? ui.textArea2.value() : '').toUpperCase();
  raw2 = raw2.replace(/\s+/g, ''); // remove all whitespace
  if (!raw2 || raw2.length === 0) return;

  const need = ROWS * COLS; // more than enough; we'll mod-index per blank
  for (let i = 0; i < need; i++) {
    // pick a single random character from second text
    const ch = raw2[floor(random(raw2.length))];
    fillerTokens.push(ch);
  }
}

// Helper to fetch single-letter token for the Nth blank
function getSingleLetterFiller(blankIdx) {
  if (!fillerTokens || fillerTokens.length === 0) return null;
  return fillerTokens[blankIdx % fillerTokens.length];
}

