  ui.panel.style('border-radius', '12px');
  ui.panel.style('backdrop-filter', 'blur(6px)');
  ui.panel.style('background', 'rgba(255,255,255,0.78)');
  ui.panel.style('box-shadow', '0 6px 22px rgba(0,0,0,0.18)');
  ui.panel.style('font-family', 'Inter, system-ui, sans-serif');
  ui.panel.style('font-size', '13px');
