  ui.typeColor = createColorPicker('#474EFF'); // default type color
  ui.bgColor.style('width', '40px');
  ui.pageColor.style('width', '40px');
  ui.typeColor.style('width', '40px');
  rowFlex('Background', ui.bgColor);
  rowFlex('Canvas (A4)', ui.pageColor);
  rowFlex('Type', ui.typeColor);

  // Grid
  title('Grid');
  ui.showGrid = createCheckbox(' Show grid (page, margin, 3×5 boxes)', true);
  ui.panel.child(ui.showGrid);

  // MAIN TEXT (Font 1)
  title('Main Text (Font 1: assets/type.otf)');
  ui.textArea = createElement('textarea');
  ui.textArea.attribute('placeholder', 'TYPE HERE — spaces create empty boxes');
  ui.textArea.style('width', '100%');
  ui.textArea.style('height', '72px');
  ui.textArea.style('padding', '8px 10px');
  ui.textArea.style('border', '1px solid #ccc');
  ui.textArea.style('border-radius', '8px');
  ui.textArea.style('resize', 'vertical');
  ui.textArea.value('EASY FUN TYPE PLAY');
  ui.panel.child(ui.textArea);

  // SECOND TEXT (Font 2)
  title('Second Text (Font 2: assets/type2.otf)');
  ui.textArea2 = createElement('textarea');
  ui.textArea2.attribute('placeholder', 'SECOND TEXT — only single letters will be used');
  ui.textArea2.style('width', '100%');
  ui.textArea2.style('height', '56px');
  ui.textArea2.style('padding', '8px 10px');
  ui.textArea2.style('border', '1px solid #ccc');
  ui.textArea2.style('border-radius', '8px');
  ui.textArea2.style('resize', 'vertical');
  ui.textArea2.input(() => { randomizeSecondFiller(); });
  ui.panel.child(ui.textArea2);

  // NOTES
  title('Notes for Empty Boxes (ignored when "Use Second Text in Blanks" is ON)');
  ui.noteAreas = [];
  for (let n = 1; n <= 4; n++) {
    const ta = createElement('textarea');
    ta.attribute('placeholder', `Note ${n} — up to 4 lines`);
    ta.style('flex', '1');
    ta.style('width', '100%');
    ta.style('height', '72px');
    ta.style('padding', '6px 8px');
    ta.style('border', '1px solid #ccc');
    ta.style('border-radius', '8px');
    ta.style('resize', 'vertical');
    const wrap = createDiv('');
    wrap.style('margin', '4px 0 6px');
    const lab = createSpan(`Note ${n}`);
    lab.style('display', 'block');
    lab.style('color', '#333');
    lab.style('margin-bottom', '4px');
    wrap.child(lab);
    wrap.child(ta);
    ui.panel.child(wrap);
    ui.noteAreas.push(ta);
  }

  // RANDOMIZER #1 controls (1-or-2 letters per non-space box)
  title('Randomizer #1 (Main boxes: 1 or 2 letters)');
  const rnd1 = createButton('Randomize Pattern Now');
  rnd1.mousePressed(() => randomizePattern1());
  ui.panel.child(rnd1);

  const wrap1 = createDiv('');
  wrap1.style('display', 'flex'); wrap1.style('gap','10px'); wrap1.style('align-items','center'); wrap1.style('margin','8px 0 0');
  ui.play1 = createButton('Play');
  ui.play1.mousePressed(() => { autoPlay1 = !autoPlay1; ui.play1.html(autoPlay1 ? 'Pause' : 'Play'); lastAuto1Ms = millis(); });
  wrap1.child(ui.play1);
  const sp1Lab = createSpan('Speed (changes/sec)');
  sp1Lab.style('margin-left','8px'); wrap1.child(sp1Lab);
  ui.speed1 = createSlider(0.2, 6.0, 1.0, 0.1);
  ui.speed1.style('width','140px'); wrap1.child(ui.speed1);
  ui.panel.child(wrap1);

  // RANDOMIZER #2 controls (fill blank boxes with second text)
  title('Randomizer #2 (Fill blanks with Second Text, ONE LETTER PER BOX)');
  ui.useSecondToggle = createCheckbox(' Use Second Text in Blanks (ignore notes)', false);
  ui.useSecondToggle.changed(() => { useSecondInBlanks = ui.useSecondToggle.checked(); });
  ui.panel.child(ui.useSecondToggle);

  const rnd2 = createButton('Randomize Fill Now (single letters)');
  rnd2.mousePressed(() => randomizeSecondFiller());
  ui.panel.child(rnd2);

  const wrap2 = createDiv('');
  wrap2.style('display', 'flex'); wrap2.style('gap','10px'); wrap2.style('align-items','center'); wrap2.style('margin','8px 0 0');
  ui.play2 = createButton('Play');
  ui.play2.mousePressed(() => { autoPlay2 = !autoPlay2; ui.play2.html(autoPlay2 ? 'Pause' : 'Play'); lastAuto2Ms = millis(); });
  wrap2.child(ui.play2);
  const sp2Lab = createSpan('Speed (changes/sec)');
  sp2Lab.style('margin-left','8px'); wrap2.child(sp2Lab);
  ui.speed2 = createSlider(0.2, 6.0, 1.0, 0.1);
  ui.speed2.style('width','140px'); wrap2.child(ui.speed2);
  ui.panel.child(wrap2);
}

function getCornerNotes() {
  const out = [];
  if (ui.noteAreas && ui.noteAreas.length) {
    for (const ta of ui.noteAreas) {
      const raw = (ta.value() || '').trim();
      if (!raw) continue;
      const lines = raw.split(/\r?\n/).slice(0, 4).map(s => s.trim());
      while (lines.length && lines[lines.length - 1] === '') lines.pop();
      if (lines.length) out.push(lines);
    }
  }
  return out;
}

/* ---------------- Status badge ---------------- */

function drawFontStatus(page) {
  const lines = [];
  lines.push(font1Ready ? `Font1 ✓ (${font1Path || 'assets/type.otf'})` : (font1Err ? 'Font1 ✗' : 'Font1 …'));
  lines.push(font2Ready ? `Font2 ✓ (${font2Path || 'assets/type2.otf'})` : (font2Err ? 'Font2 ✗' : 'Font2 …'));
  const msg = lines.join('   •   ');

  push();
  textAlign(LEFT, TOP);
  textSize(12);
  noStroke();
  const pad = 6;
  const w = textWidth(msg) + pad * 2;
  const h = 22;
  fill(255, 255, 255, 220);
  rect(page.x, page.y - h - 8, w, h, 6);
  fill(0);
  text(msg, page.x + pad, page.y - h - 6);
  pop();
}


// 1. 免疫 DOM 元素建立導致的看門狗攔截
if (typeof createP === 'undefined') { window.createP = function() { return { position: function(){}, style: function(){} }; }; }
if (typeof createDiv === 'undefined') { window.createDiv = function() { return { position: function(){}, style: function(){} }; }; }

// 2. 圖片與非同步資產載入後備自癒護欄
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origLoadImage === 'undefined') { window._origLoadImage = p5.prototype.loadImage; }
    p5.prototype.loadImage = function(path, successCallback, failureCallback) {
        if (typeof path !== 'string' || (path.startsWith('http') === false && path.startsWith('data:') === false)) {
            // 當發現是相對路徑或丟失的外部圖片資產時，使用 1x1 灰色 GIF 的 Base64 代替，防止渲染死鎖
            const dummyPath = "data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7";
            return window._origLoadImage.call(this, dummyPath, successCallback, failureCallback);
        }
        return window._origLoadImage.call(this, path, successCallback, failureCallback);
    };
}

// 3. 修正 3D 渲染圖層 WebGL 與 Canvas 2D 上下文屬性缺失
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origGet === 'undefined') { window._origGet = p5.prototype.get; }
    p5.prototype.get = function(...args) {
        if (this.width === 0 || this.height === 0) {
            return createGraphics(10, 10);
        }
        return window._origGet.apply(this, args);
    };
}
